@namespace sv_b34dd01c117544cfa45337247bb2fdd7.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link @(section == ActiveSection ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section)">
                    <span class="sidebar-icon">@GetIcon(section)</span>
                    @section
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_b34dd01c117544cfa45337247bb2fdd7.Components.Pages.Settings
@using sv_b34dd01c117544cfa45337247bb2fdd7.Services

<div class="settings-section">
    <h3>Profile</h3>

    @if (_profile is not null)
    {
        <div class="mb-3">
            <div class="avatar-preview mb-2">
                <img src="@_profile.AvatarUrl" alt="Avatar" class="rounded-circle" style="width:80px;height:80px;object-fit:cover;" />
            </div>
            <small class="text-muted">@_profile.AvatarUrl</small>
        </div>

        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="_displayName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>

        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="_bio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveChanges">Save Changes</button>
            <button class="btn btn-outline-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3" role="alert">
                Profile saved successfully!
            </div>
        }
    }
    else
    {
        <p>Loading profile...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        LoadFromProfile();
    }

    private void LoadFromProfile()
    {
        if (_profile is null) return;
        _displayName = _profile.DisplayName;
        _email = _profile.Email;
        _bio = _profile.Bio;
    }

    private async Task SaveChanges()
    {
        var updated = _profile! with { DisplayName = _displayName, Email = _email, Bio = _bio };
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DiscardChanges()
    {
        LoadFromProfile();
        _showSuccess = false;
    }
}

@namespace sv_b34dd01c117544cfa45337247bb2fdd7.Components.Pages.Settings
@using sv_b34dd01c117544cfa45337247bb2fdd7.Services

<div class="settings-section">
    <h3>Notifications</h3>

    @if (_prefs is not null)
    {
        <div class="mb-4">
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <h5>Muted Channels</h5>
        <div class="mb-3">
            @foreach (var channel in _allChannels)
            {
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                    <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SavePreferences">Save Preferences</button>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3" role="alert">
                Notification preferences saved!
            </div>
        }
    }
    else
    {
        <p>Loading notification preferences...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _showSuccess;

    private static readonly string[] _allChannels = { "general", "marketing", "engineering", "announcements", "random" };

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(_prefs.MutedChannels);
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _prefs = updated;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_b34dd01c117544cfa45337247bb2fdd7.Components.Pages.Settings

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center"
         style="cursor:pointer;" @onclick="ToggleExpanded">
        <strong>Change Password</strong>
        <span>@(_expanded ? "▲" : "▼")</span>
    </div>
    @if (_expanded)
    {
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="_currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="_newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm Password</label>
                <input type="password" class="form-control" @bind="_confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="alert alert-danger">@_error</div>
            }
            @if (_success)
            {
                <div class="alert alert-success">Password updated successfully!</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string current, string newPwd)> OnChangePassword { get; set; }

    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _error;
    private bool _success;

    private void ToggleExpanded() => _expanded = !_expanded;

    private async Task UpdatePassword()
    {
        _error = null;
        _success = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _error = "All fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _error = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _success = true;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }
}

@namespace sv_b34dd01c117544cfa45337247bb2fdd7.Components.Pages.Settings
@using sv_b34dd01c117544cfa45337247bb2fdd7.Services

<h5>Active Sessions</h5>
<div class="table-responsive">
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@session.LastActive.ToString("g")</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            @if (_confirmingSessionId == session.Id)
                            {
                                <span class="me-2">Revoke this session?</span>
                                <button class="btn btn-danger btn-sm me-1" @onclick="() => ConfirmRevoke(session.Id)">Yes</button>
                                <button class="btn btn-secondary btn-sm" @onclick="CancelRevoke">No</button>
                            }
                            else
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">Revoke</button>
                            }
                        }
                        else
                        {
                            <span class="badge bg-success">Current</span>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "session-1";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private string? _confirmingSessionId;

    private void RequestRevoke(string sessionId)
    {
        _confirmingSessionId = sessionId;
    }

    private void CancelRevoke()
    {
        _confirmingSessionId = null;
    }

    private async Task ConfirmRevoke(string sessionId)
    {
        _confirmingSessionId = null;
        await OnRevoke.InvokeAsync(sessionId);
    }
}

@namespace sv_b34dd01c117544cfa45337247bb2fdd7.Components.Pages.Settings
@using sv_b34dd01c117544cfa45337247bb2fdd7.Services

<div class="settings-section">
    <h3>Security</h3>

    @if (_settings is not null)
    {
        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

        <div class="mb-4">
            <h5>Two-Factor Authentication</h5>
            <div class="d-flex align-items-center gap-2">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@_settings.TwoFactorEnabled" disabled />
                    <label class="form-check-label" for="twoFactor">
                        @(_settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                    </label>
                </div>
                <span class="badge @(_settings.TwoFactorEnabled ? "bg-success" : "bg-warning")">
                    @(_settings.TwoFactorEnabled ? "Active" : "Inactive")
                </span>
            </div>
            @if (_settings.LastPasswordChange.HasValue)
            {
                <small class="text-muted d-block mt-2">
                    Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </small>
            }
        </div>

        <ActiveSessionsTable Sessions="@_settings.Sessions.ToList()"
                             CurrentSessionId="session-1"
                             OnRevoke="HandleRevoke" />
    }
    else
