{"file_text": "@namespace sv_b34dd01c117544cfa45337247bb2fdd7.Components.Pages.Settings
@using sv_b34dd01c117544cfa45337247bb2fdd7.Services

<div class="settings-section">
    <h3>Appearance</h3>

    @if (_settings is not null)
    {
        <div class="mb-4">
            <h5>Theme</h5>
            <div class="d-flex gap-3">
                @foreach (var theme in _themes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>
        </div>

        <div class="mb-4">
            <h5>Font Size</h5>
            <div class="d-flex gap-3">
                @foreach (var size in _fontSizes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>
        </div>

        <div class="mb-4">
            <h5>Language</h5>
            <select class="form-select" style="max-width:200px;" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <div class="mb-4">
            <h5>Live Preview</h5>
            <div class="preview-area p-3 border rounded" style="@GetPreviewStyle()">
                <p class="mb-1"><strong>Preview Text</strong></p>
                <p class="mb-1">This is how your content will look with the selected settings.</p>
                <button class="btn btn-sm btn-primary">Sample Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="Save">Save</button>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3" role="alert">
                Appearance settings saved!
            </div>
        }
    }
    else
    {
        <p>Loading appearance settings...</p>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private AppearanceSettings? _settings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _showSuccess;

    private static readonly string[] _themes = { "Light", "Dark", "System" };
    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetAppearanceAsync();
        _theme = _settings.Theme;
        _fontSize = _settings.FontSize;
        _language = _settings.Language;
        _compactMode = _settings.CompactMode;
    }

    private string GetPreviewStyle()
    {
        var bg = _theme == "Dark" ? "#1e1e1e" : "#ffffff";
        var fg = _theme == "Dark" ? "#e0e0e0" : "#212529";
        var fs = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.2rem",
            _ => "1rem"
        };
        var padding = _compactMode ? "0.5rem" : "1rem";
        return $"background-color:{bg};color:{fg};font-size:{fs};padding:{padding};";
    }

    private async Task Save()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _settings = updated;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
