+<h5>Active Sessions</h5>
+<div class="table-responsive">
+    <table class="table table-striped">
+        <thead>
+            <tr>
+                <th>Device</th>
+                <th>Location</th>
+                <th>Last Active</th>
+                <th></th>
+            </tr>
+        </thead>
+        <tbody>
+            @foreach (var session in Sessions)
+            {
+                <tr>
+                    <td>@session.Device</td>
+                    <td>@session.Location</td>
+                    <td>@session.LastActive.ToString("g")</td>
+                    <td>
+                        @if (session.Id != CurrentSessionId)
+                        {
+                            @if (_confirmingSessionId == session.Id)
+                            {
+                                <span class="me-2">Revoke this session?</span>
+                                <button class="btn btn-danger btn-sm me-1" @onclick="() => ConfirmRevoke(session.Id)">Yes</button>
+                                <button class="btn btn-secondary btn-sm" @onclick="CancelRevoke">No</button>
+                            }
+                            else
+                            {
+                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">Revoke</button>
+                            }
+                        }
+                        else
+                        {
+                            <span class="badge bg-success">Current</span>
+                        }
+                    </td>
+                </tr>
+            }
+        </tbody>
+    </table>
+</div>
+
+@code {
+    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
+    [Parameter] public string CurrentSessionId { get; set; } = "session-1";
+    [Parameter] public EventCallback<string> OnRevoke { get; set; }
+
+    private string? _confirmingSessionId;
+
+    private void RequestRevoke(string sessionId)
+    {
+        _confirmingSessionId = sessionId;
+    }
+
+    private void CancelRevoke()
+    {
+        _confirmingSessionId = null;
+    }
+
+    private async Task ConfirmRevoke(string sessionId)
+    {
+        _confirmingSessionId = null;
+        await OnRevoke.InvokeAsync(sessionId);
+    }
+}
+

