toolArgs.file_text:
.settings-dashboard {
    min-height: 600px;
}

.settings-sidebar-container {
    width: 220px;
    border-right: 1px solid #dee2e6;
    min-height: 600px;
}

::deep .settings-sidebar .nav-link {
    color: #495057;
    border-radius: 0;
    padding: 0.75rem 1.25rem;
    text-align: left;
    width: 100%;
    border: none;
    background: none;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: #f8f9fa;
}

::deep .settings-sidebar .nav-link.active {
    background-color: #e7f1ff;
    color: #0d6efd;
    font-weight: 600;
    border-left: 3px solid #0d6efd;
}

::deep .settings-section {
    max-width: 700px;
}

::deep .preview-area {
    min-height: 100px;
    transition: all 0.3s ease;
}

